<# Post-handoff only: detach owned shadow, protect offline target, online read-only. #>
[CmdletBinding(SupportsShouldProcess)]param(
 [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{32}\z')][string]$RunId,
 [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{32}\z')][string]$ObservationId,
 [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{32}\z')][string]$ApplyPhaseId,
 [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{32}\z')][string]$HandoffPhaseId,
 [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{64}\z')][string]$ShadowPreparationSha256,
 [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{64}\z')][string]$RequestSha256,
 [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{64}\z')][string]$TicketSha256,
 [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{64}\z')][string]$ApplyResultSha256,
 [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{64}\z')][string]$HandoffResultSha256,
 [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{64}\z')][string]$ApplyProcessSha256,
 [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{64}\z')][string]$HandoffProcessSha256,
 [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{64}\z')][string]$ShadowNativeSourceSha256,
 [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{64}\z')][string]$MountNativeSourceSha256
)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
function Assert-MountBool($Value,[bool]$Expected){if($Value -isnot [bool] -or $Value -ne $Expected){throw 'Explicit mount-boundary boolean differs.'}}
function Assert-MountHash($Value){if($Value -isnot [string] -or $Value -cnotmatch '\A[0-9a-f]{64}\z'){throw 'Exact SHA-256 required.'}}
function Assert-MountInteger($Value,[long]$Minimum,[long]$Maximum){if(($Value -isnot [int] -and $Value -isnot [long] -and $Value -isnot [uint32] -and $Value -isnot [uint64]) -or $Value -lt $Minimum -or $Value -gt $Maximum){throw 'Bounded integer required.'}}
function Assert-MountGuid([string]$Value){if($Value -cnotmatch '\A(?:[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}|\{[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}\})\z' -or [guid]$Value -eq [guid]::Empty){throw 'Exact nonempty GUID required.'}}
function Assert-MountSame($Expected,$Actual){
 if($null -eq $Expected -or $null -eq $Actual){if($null -ne $Expected -or $null -ne $Actual){throw 'Pinned evidence null differs.'};return}
 if($Expected -is [pscustomobject]){if($Actual -isnot [pscustomobject] -or @($Expected.PSObject.Properties).Count -ne @($Actual.PSObject.Properties).Count){throw 'Pinned object differs.'};foreach($n in $Expected.PSObject.Properties.Name){if($n -cnotin $Actual.PSObject.Properties.Name){throw 'Pinned field missing.'};Assert-MountSame $Expected.$n $Actual.$n};return}
 if($Expected -is [array]){if($Actual -isnot [array] -or $Expected.Count -ne $Actual.Count){throw 'Pinned sequence differs.'};for($i=0;$i -lt $Expected.Count;$i++){Assert-MountSame $Expected[$i] $Actual[$i]};return}
 if($Expected -is [string]){if($Actual -isnot [string] -or $Expected -cne $Actual){throw 'Pinned string differs.'};return}
 if($Expected -is [bool]){Assert-MountBool $Actual $Expected;return};if($Actual -is [string] -or $Actual -is [bool] -or $Expected -ne $Actual){throw 'Pinned value differs.'}
}
function Assert-MountProfile($Binding,[int]$Number,[long]$DiskBytes,[long]$PartitionBytes){
 $i=$Binding.identity;foreach($g in @($i.disk_guid,$i.partition_guid,$Binding.volume_guid)){Assert-MountGuid $g}
 if($Binding.disk_number -ne $Number -or $i.partition_number -ne 2 -or $i.disk_bytes -ne $DiskBytes -or $i.partition_offset -ne 16MB -or $i.partition_bytes -ne $PartitionBytes -or $i.logical_sector_bytes -ne 512 -or $i.physical_sector_bytes -ne 4096){throw 'Enrolled native geometry differs.'}
}
function Assert-MountInputs($Preparation,$Request,$Ticket,[string]$ExpectedRun,[string]$ExpectedShadowNative){
 $p=$Preparation;$r=$Request;$t=$Ticket
 if($p.schemaVersion -ne 1 -or $p.kind -cne 'guest-local-shadow-platform' -or $p.status -cne 'shadow-platform-prepared' -or $p.runId -cne $ExpectedRun -or $p.nativeSourceSha256 -cne $ExpectedShadowNative -or $p.backingPath -cne ('J:\ntfs2refs-shadow\'+$ExpectedRun+'\shadow.vhdx')){throw 'Shadow platform evidence differs.'}
 foreach($name in @('attachmentRetained','handleCloseSucceeded','nativeOperationCompletionKnown','privilegeRestored')){Assert-MountBool $p.$name $true}
 foreach($name in @('sourceTargetWriteRequestsIssued','payloadCopied','conversionQualified','bootQualified')){Assert-MountBool $p.$name $false}
 if($p.vhdIdentityQueryVersion -ne 14 -or $p.finalVhd.virtualDiskIdQueryVersion -ne 14 -or [guid]$p.finalVhd.virtualDiskId -ne [guid]$p.vhdIdentifier -or $p.finalVhd.virtualBytes -ne 64GB -or $p.finalVhd.blockBytes -ne 2MB -or $p.finalVhd.logicalSectorBytes -ne 512 -or $p.finalVhd.physicalSectorBytes -ne 4096 -or $p.finalVhd.providerSubtype -ne 3 -or $p.finalVhd.physicalPath -cne '\\.\PhysicalDrive3'){throw 'Stable shadow identity differs.'};Assert-MountGuid $p.finalVhd.virtualDiskId
 if($r.schema_version -ne 1 -or $r.experiment_id -cne $ExpectedRun -or $r.probe.schema_version -ne 1 -or $r.probe.experiment_id -cne $ExpectedRun){throw 'Reconstruction request identity differs.'}
 Assert-MountProfile $r.probe.target 1 64GB 52GB;Assert-MountProfile $r.probe.shadow 3 64GB 52GB;Assert-MountProfile $r.journal 2 8GB (8GB-32MB)
 if($r.journal.externally_enrolled_disk_unique_id -cne '600224806AAC261F021F249596F332FC' -or $p.journalIdentity.uniqueId -cne $r.journal.externally_enrolled_disk_unique_id){throw 'Journal enrollment differs.'}
 foreach($role in @('shadow','journal')){$b=if($role -ceq 'shadow'){$r.probe.shadow}else{$r.journal};$x=$p.$role;if($x.diskNumber -ne $b.disk_number -or [guid]$x.diskGuid -ne [guid]$b.identity.disk_guid -or [guid]$x.partitionGuid -ne [guid]$b.identity.partition_guid -or $x.partitionNumber -ne 2 -or $x.offset -ne 16MB -or $x.length -ne $b.identity.partition_bytes -or $x.volumeGuid -ine ('\\?\Volume{'+([guid]$b.volume_guid).ToString('D')+'}\')){throw 'Platform and request identities differ.'}}
 foreach($field in @('disk_guid','partition_guid')){$all=@($r.probe.target.identity.$field,$r.probe.shadow.identity.$field,$r.journal.identity.$field);if(@($all|ForEach-Object{[guid]$_}|Select-Object -Unique).Count -ne 3){throw 'Storage identities overlap.'}}
 foreach($hash in @($r.probe.fixture_evidence_sha256,$r.probe.source_retained_sha256,$r.probe.shadow_retained_sha256,$r.comparison.source_sha256,$r.comparison.shadow_sha256,$t.immutable_sha256)){Assert-MountHash $hash}
 $range=@($r.comparison.retained_ranges);if($r.comparison.schema_version -ne 1 -or $r.comparison.sector_size -ne 4096 -or $r.comparison.expected_length -ne 52GB -or $r.comparison.max_change_bytes -le 0 -or $r.comparison.max_change_bytes -gt 256MB -or $r.comparison.max_ranges -lt 1 -or $r.comparison.max_ranges -gt 65536 -or $range.Count -ne 1 -or $range[0].offset -ne $r.probe.retained_offset -or $range[0].length -ne 65536 -or $range[0].source_sha256 -cne $r.probe.source_retained_sha256 -or $range[0].shadow_sha256 -cne $r.probe.shadow_retained_sha256 -or $r.probe.retained_offset -lt 8GB -or $r.probe.retained_offset -gt (9GB-65536) -or ($r.probe.retained_offset%4096) -ne 0 -or $r.probe.source_retained_sha256 -ceq $r.probe.shadow_retained_sha256){throw 'Retained comparison profile differs.'}
 if($r.max_journal_bytes -lt 8192 -or $r.max_journal_bytes -gt 768MB -or $t.schema_version -ne 1 -or $t.binding.experiment_id -cne $ExpectedRun -or $t.journal_length -gt $r.max_journal_bytes -or $t.journal_length -lt 8192 -or $t.immutable_length -le 0 -or ($t.immutable_length+8192) -ne $t.journal_length){throw 'Durable ticket shape differs.'};foreach($name in @('target_identity_sha256','shadow_identity_sha256','journal_identity_sha256')){Assert-MountHash $t.binding.$name}
}
function Assert-MountCli($Report,$Request,$Ticket,[string]$Operation,[string]$RequestHash,[string]$TicketHash,[string]$PhaseRoot){
 $c=$Report;$n=$c.native
 if($Operation -cnotin @('apply','handoff') -or $c.schema_version -ne 1 -or $c.kind -cne 'native-reconstruction-cli-result' -or $c.operation -cne $Operation -or $c.phase -cne 'complete-disks-remain-offline' -or $null -ne $c.error -or $c.request_sha256 -cne $RequestHash -or $c.input_ticket_sha256 -cne $TicketHash -or $c.journal_path -cne ('J:\ntfs2refs-shadow\'+$Request.experiment_id+'\reconstruction.journal') -or $c.intent_path -cne ($PhaseRoot+'\result.intent.json')){throw 'Completed CLI evidence differs.'};Assert-MountHash $c.intent_sha256
 foreach($name in @('success','journal_open_attempted','native_operation_invoked','artifacts_preserved_on_failure')){Assert-MountBool $c.$name $true};foreach($name in @('journal_create_may_have_been_issued','ticket_write_may_have_been_issued','ticket_persisted','online_transition_requested','conversion_qualified','boot_qualified')){Assert-MountBool $c.$name $false}
 if($n.schema_version -ne 1 -or $n.kind -cne 'native-lab-journal-reconstruction' -or $n.operation -cne $Operation -or $n.phase -cne 'complete-disks-remain-offline' -or $null -ne $n.error){throw 'Completed native reconstruction evidence differs.'};Assert-MountSame $Request $n.request;Assert-MountSame $Ticket.binding $n.observed_binding
 foreach($name in @('success','disks_observed_offline_at_end','journal_write_requests_may_have_been_issued')){Assert-MountBool $n.$name $true};foreach($name in @('online_transition_requested','conversion_qualified','boot_qualified')){Assert-MountBool $n.$name $false}
 foreach($role in @('target','shadow')){foreach($when in @('before','after')){$s=$n.($role+'_'+$when);Assert-MountSame $Request.probe.$role $s.binding;if($s.disk_attributes -ne $(if($role -ceq 'target'){1}else{3})){throw 'Reconstruction did not finish offline in the exact state.'}}}
 if($n.plan.immutable_sha256 -cne $Ticket.immutable_sha256 -or $n.plan.patch_count -lt 1 -or $n.plan.patch_count -gt $Request.comparison.max_ranges -or $n.plan.changed_bytes -le 0 -or $n.plan.changed_bytes -gt $Request.comparison.max_change_bytes){throw 'Pinned journal plan differs.'};Assert-MountHash $n.plan.expected_postimage_sha256
 $e=$n.execution;Assert-MountBool $e.retained_bytes_unchanged $true;Assert-MountBool $e.conversion_qualified $false;Assert-MountBool $e.handoff_recorded ($Operation -ceq 'handoff');Assert-MountBool $n.handoff_request_may_have_been_issued ($Operation -ceq 'handoff');Assert-MountBool $n.payload_write_requests_issued ($Operation -ceq 'apply')
 if($e.operation -cne $(if($Operation -ceq 'apply'){'applied-before-handoff'}else{'handoff-recorded'}) -or $e.target_sha256 -cne $n.plan.expected_postimage_sha256 -or $n.counters.shadow_bytes_written -ne 0 -or $n.counters.shadow_write_bytes_requested -ne 0){throw 'Complete postimage/retained proof differs.'}
 $written=if($Operation -ceq 'apply'){$n.plan.changed_bytes}else{0};if($e.target_bytes_written -ne $written -or $n.counters.target_bytes_written -ne $written -or $n.counters.target_write_bytes_requested -ne $written -or $e.patches_written -ne $(if($Operation -ceq 'apply'){$n.plan.patch_count}else{0})){throw 'Exact target write accounting differs.'}
 foreach($when in @('before','after')){$j=$n.('journal_'+$when);if($j.file_bytes -ne $Ticket.journal_length -or $j.disk_number -ne 2){throw 'Journal storage/length differs.'}}
}
function Assert-MountProcess($Record,[string]$ExpectedRun,[string]$ExpectedPhase,[string]$Operation,[string]$RequestHash,[string]$TicketHash){
 if($Record.schemaVersion -ne 1 -or $Record.kind -cne 'native-reconstruction-process' -or $Record.runId -cne $ExpectedRun -or $Record.phaseId -cne $ExpectedPhase -or $Record.operation -cne $Operation -or $Record.requestSha256 -cne $RequestHash -or $Record.independentTicketSha256 -cne $TicketHash -or $Record.ticketSha256 -cne $TicketHash -or $Record.status -cne 'native-reconstruction-phase-verified-disks-offline'){throw 'Completed reconstruction process differs.'};Assert-MountInteger $Record.processId 1 ([uint32]::MaxValue);Assert-MountInteger $Record.exitCode 0 0;foreach($name in @('completionKnown','launchAttempted','nativeResultVerified','statePreservationRequired','processIntentPersisted')){Assert-MountBool $Record.$name $true};foreach($name in @('onlineTransitionRequested','conversionQualified')){Assert-MountBool $Record.$name $false};Assert-MountHash $Record.binarySha256
}
function Assert-MountProcessArtifacts($Process,[string]$ResultHash,[string]$IntentHash){
 $files=@($Process.artifacts);if($files.Count -ne 4 -or @($files.name|Select-Object -Unique).Count -ne 4){throw 'Process artifact inventory differs.'}
 foreach($f in $files){Assert-MountHash $f.sha256;$limit=switch -CaseSensitive ($f.name){'result.json'{16MB};'result.intent.json'{256KB};'reconstruct.stdout'{64KB};'reconstruct.stderr'{64KB};default{throw 'Unexpected process artifact.'}};if($f.length -lt 0 -or $f.length -gt $limit -or ($f.name -like '*.json' -and $f.length -lt 1)){throw 'Process artifact bounds differ.'};if(($f.name -ceq 'result.json' -and $f.sha256 -cne $ResultHash) -or ($f.name -ceq 'result.intent.json' -and $f.sha256 -cne $IntentHash)){throw 'Process completed a different native report/intent.'}}
}
function Assert-MountInventory([object[]]$Disks,$Preparation,[bool]$WithShadow,[int]$TargetAttributes,$Request){
 $ids=@('60022480BEA35BA9D496D5AFF633D768','60022480D091C4251B5FFD619706C2B5','600224806AAC261F021F249596F332FC');$wanted=if($WithShadow){4}else{3};if($Disks.Count -ne $wanted){throw 'Unexpected physical disk inventory.'}
 for($i=0;$i -lt $wanted;$i++){$d=@($Disks|Where-Object Number -EQ $i);$uid=if($i -eq 3){$Preparation.shadow.diskUniqueId}else{$ids[$i]};if($d.Count -ne 1 -or $d[0].UniqueId -cne $uid -or $d[0].Size -ne $(if($i -eq 2){8GB}else{64GB}) -or $d[0].LogicalSectorSize -ne 512 -or $d[0].PhysicalSectorSize -ne 4096){throw 'Physical disk enrollment differs.'};$d=$d[0]
  if($i -eq 0){if(-not $d.IsBoot -or -not $d.IsSystem -or $d.IsOffline -or $d.IsReadOnly){throw 'OS state differs.'};continue};if($d.IsBoot -or $d.IsSystem -or $d.PartitionStyle -cne 'GPT'){throw 'Data disk role differs.'}
  $binding=if($i -eq 1){$Request.probe.target}elseif($i -eq 2){$Request.journal}else{$Request.probe.shadow};$attrs=if($i -eq 1){$TargetAttributes}elseif($i -eq 2){0}else{3};if([guid]$d.Guid -ne [guid]$binding.identity.disk_guid -or [bool]$d.IsOffline -ne [bool]($attrs-band1) -or [bool]$d.IsReadOnly -ne [bool]($attrs-band2)){throw 'Persistent physical identity/state differs.'}
 }
}
function Assert-MountOrdinary([string]$Path,[switch]$Directory){$f=Get-Item -LiteralPath $Path -Force;if([bool]$f.PSIsContainer -ne [bool]$Directory -or ($f.Attributes -band ([IO.FileAttributes]::ReparsePoint -bor [IO.FileAttributes]::Compressed -bor [IO.FileAttributes]::Encrypted))){throw 'Ordinary path required.'};$f}
function Assert-MountAncestors([string]$Path){$p=[IO.Path]::GetDirectoryName($Path);while($p){Assert-MountOrdinary $p -Directory|Out-Null;$next=[IO.Path]::GetDirectoryName($p);if($next -eq $p){break};$p=$next}}
function Read-MountPinned([string]$Path,[string]$Hash,[long]$Maximum,[switch]$Text){Assert-MountAncestors $Path;$f=Assert-MountOrdinary $Path;if($f.Length -lt 1 -or $f.Length -gt $Maximum){throw 'Pinned file bound differs.'};$s=New-Object IO.FileStream($Path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);$script:inputHandles.Add($s);if($s.Length -ne $f.Length){throw 'Pinned file length changed.'};$sha=[Security.Cryptography.SHA256]::Create();try{$actual=[BitConverter]::ToString($sha.ComputeHash($s)).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()};if($actual -cne $Hash){throw 'Pinned file hash differs.'};$s.Position=0;$reader=New-Object IO.StreamReader($s,(New-Object Text.UTF8Encoding($false,$true)),$true,4096,$true);try{$value=$reader.ReadToEnd()}finally{$reader.Dispose()};if($Text){return $value};$value|ConvertFrom-Json}
function New-MountDirectory([string]$Path){if(Test-Path -LiteralPath $Path){throw 'Evidence directory exists.'};New-Item -ItemType Directory -Path $Path|Out-Null;$acl=New-Object Security.AccessControl.DirectorySecurity;$acl.SetAccessRuleProtection($true,$false);foreach($sid in @('S-1-5-18','S-1-5-32-544')){$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule((New-Object Security.Principal.SecurityIdentifier($sid)),[Security.AccessControl.FileSystemRights]::FullControl,([Security.AccessControl.InheritanceFlags]::ContainerInherit -bor [Security.AccessControl.InheritanceFlags]::ObjectInherit),[Security.AccessControl.PropagationFlags]::None,[Security.AccessControl.AccessControlType]::Allow)))};Set-Acl -LiteralPath $Path -AclObject $acl;Assert-MountOrdinary $Path -Directory|Out-Null}
function Save-MountStage([string]$Stage){$record.stage=$Stage;$record.updatedUtc=[DateTime]::UtcNow.ToString('o');if($native){$record.native=$native};$bytes=(New-Object Text.UTF8Encoding($false)).GetBytes(($record|ConvertTo-Json -Depth 28));if($bytes.Length -gt 2MB){throw 'Mount evidence exceeds 2 MiB bound.'};$evidenceStream.Position=0;$evidenceStream.SetLength(0);$evidenceStream.Write($bytes,0,$bytes.Length);$evidenceStream.Flush($true)}

if(-not $PSCmdlet.ShouldProcess('proven post-handoff target and owned shadow','Detach shadow and expose target read-only')){[pscustomobject]@{Status='what-if';ConversionQualified=$false};return}
if($RunId.Length -ne 32 -or $ObservationId.Length -ne 32 -or $ApplyPhaseId.Length -ne 32 -or $HandoffPhaseId.Length -ne 32 -or $ApplyPhaseId -ceq $HandoffPhaseId -or $env:COMPUTERNAME -cne 'N2R-WIN11' -or $env:SystemDrive -cne 'C:' -or -not [Environment]::Is64BitProcess){throw 'Unexpected guest/identifiers.'}
