 $applyProcess=Read-MountPinned ($applyRoot+'\process-result.json') $ApplyProcessSha256 128KB;$handoffProcess=Read-MountPinned ($handoffRoot+'\process-result.json') $HandoffProcessSha256 128KB
 Assert-MountProcess $applyProcess $RunId $ApplyPhaseId apply $RequestSha256 $TicketSha256;Assert-MountProcess $handoffProcess $RunId $HandoffPhaseId handoff $RequestSha256 $TicketSha256
 Assert-MountProcessArtifacts $applyProcess $ApplyResultSha256 $apply.intent_sha256;Assert-MountProcessArtifacts $handoffProcess $HandoffResultSha256 $handoff.intent_sha256
