 $parent='C:\ntfs2refs\converted-mount';Assert-MountOrdinary 'C:\ntfs2refs' -Directory|Out-Null;if(-not(Test-Path -LiteralPath $parent)){New-MountDirectory $parent};Assert-MountOrdinary $parent -Directory|Out-Null;$runRoot=$parent+'\'+$RunId;if(-not(Test-Path -LiteralPath $runRoot)){New-MountDirectory $runRoot};Assert-MountOrdinary $runRoot -Directory|Out-Null;$outputRoot=$runRoot+'\'+$ObservationId;New-MountDirectory $outputRoot
 $evidenceStream=New-Object IO.FileStream(($outputRoot+'\mount.json'),[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read)
 $record=[ordered]@{schemaVersion=1;kind='converted-retained-mount-boundary';runId=$RunId;observationId=$ObservationId;status='started';stage='preflight';createdUtc=[DateTime]::UtcNow.ToString('o');pins=[ordered]@{shadowPreparationSha256=$ShadowPreparationSha256;requestSha256=$RequestSha256;ticketSha256=$TicketSha256;applyPhaseId=$ApplyPhaseId;applyResultSha256=$ApplyResultSha256;applyProcessSha256=$ApplyProcessSha256;handoffPhaseId=$HandoffPhaseId;handoffResultSha256=$HandoffResultSha256;handoffProcessSha256=$HandoffProcessSha256;shadowNativeSourceSha256=$ShadowNativeSourceSha256;mountNativeSourceSha256=$MountNativeSourceSha256;scriptSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant()};request=$request;expectedPostimageSha256=$apply.native.plan.expected_postimage_sha256;expectedTarget=$request.probe.target;expectedShadow=$prep.shadow;shadowBackingPath=$prep.backingPath;shadowVirtualDiskId=$prep.finalVhd.virtualDiskId;shadowIdentityQueryVersion=14;initialDisks=@($initial|Select-Object Number,UniqueId,Guid,Size,LogicalSectorSize,PhysicalSectorSize,PartitionStyle,IsBoot,IsSystem,IsOffline,IsReadOnly);afterDetachDisks=$null;finalDisks=$null;native=$null;operationCompletionKnown=$true;cleanupComplete=$false;shadowDetached=$false;targetOnlineReadOnly=$false;privilegeAdjustmentAttempted=$false;privilegePolicy='Windows client: one detach attempt, no privilege adjustment or retry';rawPayloadWriteRequestsIssued=$false;filePayloadWriteRequestsIssued=$false;writableMountRequested=$false;targetVolumeDiscoveryRequired=$true;convertedFileVerificationPerformed=$false;conversionQualified=$false;bootQualified=$false}
